git fetch {upstream_remote}
if ! git merge --no-edit {upstream_remote}/{upstream_branch}; then
  if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
    exit 1
  fi
fi
if git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  base=$(git merge-base HEAD MERGE_HEAD)
  up=$(git rev-parse MERGE_HEAD)
  git diff --name-only --diff-filter=U -z | while IFS= read -r -d '' p; do
    [ -n "$p" ] || continue
    ours=$(mktemp)
    add=$(mktemp)
    out=$(mktemp)
    diff=$(mktemp)
    if ! git show :2:"$p" > "$ours" 2>/dev/null; then
      if git show :3:"$p" > "$out" 2>/dev/null; then
        cat "$out" > "$p"
        git add -- "$p"
      fi
      rm -f "$ours" "$add" "$out" "$diff"
      continue
    fi
    git diff --no-color --no-ext-diff --unified=0 "$base" "$up" -- "$p" > "$diff"
    awk '
      function flush() {
        if (in_hunk && !has_del) {
          for (i = 1; i <= nadd; i++) print addlines[i]
        }
        nadd = 0
        has_del = 0
      }
      /^@@/ {
        flush()
        in_hunk = 1
        next
      }
      in_hunk {
        c = substr($0, 1, 1)
        if (c == "-") { has_del = 1 }
        else if (c == "+") { addlines[++nadd] = substr($0, 2) }
        else if (c == "\\") { }
        else { flush(); in_hunk = 0 }
      }
      END { flush() }
    ' "$diff" > "$add"
    if [ -s "$add" ]; then
      awk -v addfile="$add" '
        BEGIN {
          while ((getline line < addfile) > 0) { add[++na] = line }
          close(addfile)
        }
        { lines[NR] = $0 }
        END {
          pos = NR + 1
          for (i = NR; i >= 1; i--) {
            tmp = lines[i]
            sub(/^[[:space:]]+/, "", tmp)
            sub(/[[:space:]]+$/, "", tmp)
            if (tmp == "]" || tmp == "}") { pos = i; break }
          }
          for (i = 1; i <= NR; i++) {
            if (i == pos) {
              for (j = 1; j <= na; j++) {
                dup = 0
                for (k = 1; k <= NR; k++) if (lines[k] == add[j]) { dup = 1; break }
                if (seen[add[j]]) dup = 1
                if (!dup) { print add[j]; seen[add[j]] = 1 }
              }
            }
            print lines[i]
          }
          if (pos == NR + 1) {
            for (j = 1; j <= na; j++) {
              dup = 0
              for (k = 1; k <= NR; k++) if (lines[k] == add[j]) { dup = 1; break }
              if (seen[add[j]]) dup = 1
              if (!dup) { print add[j]; seen[add[j]] = 1 }
            }
          }
        }
      ' "$ours" > "$out"
    else
      cp "$ours" "$out"
    fi
    cat "$out" > "$p"
    git add -- "$p"
    rm -f "$ours" "$add" "$out" "$diff"
  done
  git commit --no-edit
fi
